1	/** A cell's position on the infinite grid, as [x, y]. */
2	export type Cell = [x: number, y: number];
3	
4	/** A live cell with 2 or 3 live neighbours survives; fewer or more kills it. */
5	const SURVIVAL_NEIGHBOURS = [2, 3];
6	
7	/** A dead cell with exactly this many live neighbours is born. */
8	const BIRTH_NEIGHBOURS = 3;
9	
10	/** The 8 cells surrounding a position, in reading order. */
11	const neighboursOf = ([x, y]: Cell): Cell[] => [
12	  [x - 1, y - 1],
13	  [x, y - 1],
14	  [x + 1, y - 1],
15	  [x - 1, y],
16	  [x + 1, y],
17	  [x - 1, y + 1],
18	  [x, y + 1],
19	  [x + 1, y + 1],
20	];
21	
22	/**
23	 * Cell tuples are compared by reference, so they cannot be used as Set members
24	 * directly. These convert between a cell and a value-comparable key.
25	 */
26	const toKey = ([x, y]: Cell): string => `${x},${y}`;
27	const fromKey = (key: string): Cell => {
28	  const [x, y] = key.split(",").map(Number);
29	  return [x, y];
30	};
31	
32	export function nextGeneration(liveCells: Cell[]): Cell[] {
33	  const liveKeys = new Set(liveCells.map(toKey));
34	
35	  const countLiveNeighbours = (cell: Cell): number =>
36	    neighboursOf(cell).filter((neighbour) => liveKeys.has(toKey(neighbour)))
37	      .length;
38	
39	  const isAliveNextGeneration = (cell: Cell): boolean => {
40	    const liveNeighbours = countLiveNeighbours(cell);
41	
42	    return liveKeys.has(toKey(cell))
43	      ? SURVIVAL_NEIGHBOURS.includes(liveNeighbours)
44	      : liveNeighbours === BIRTH_NEIGHBOURS;
45	  };
46	
47	  // Only live cells and their neighbours can be alive next generation —
48	  // everywhere else has 0 live neighbours and stays dead.
49	  const candidates = new Set(
50	    liveCells.flatMap((cell) => [cell, ...neighboursOf(cell)]).map(toKey),
51	  );
52	
53	  return [...candidates].map(fromKey).filter(isAliveNextGeneration);
54	}
